@module sonority  src=sonority.lua  loc=301  mode=namespace  self=sonority

# Invariants & contracts
  @invariant  pure module: no state, no ratios, no cents — coords/strikes/releases/classes → indices  @ 4

# Shapes
  @shape  Coords = {[oddPrime]=exponent}; prime 2 is absent, so the score reads harmony not spacing  @ 5
  @shape  Strand = { notes={ {ppq,pitch,endppq,..},.. }, class=<step-class>, shortlist={ Candidate,.. } }; the walk reads the strikes, the releases and the class  @ 6
  @shape  Sonority = { ppq, strands={ strandIndex,.. } }; most recently struck first, the last n struck and whatever else still sounds  @ 7
  @shape  Candidate = { coords=Coords, strain=<distance from the written step, in half-windows> }  @ 8

# Imports
  @const util = 'util'  @ 10

# Module-level constants
  @const sonority = {}  @ 11
  @const weights = {}  @ 16
  @const budget = 200000  @ 195

# Private functions
  -- The box
  @fn weight(prime)  @ 17-21
  -- The strands
  -- The walk
  @fn strikesInOrder(strands)  @ 85-98
      -- Every strike, in onset order, lowest last — so a released chord leaves its
      -- bass to the sonority that follows (design/adaptive-tuning.md § The model).
  @fn sounding(strand, ppq)  @ 102-107
      -- Half-open, so a note released where the next is struck does not sound there,
      -- and a passage whose notes stop as the next begin reads as the last n struck.
  @fn promote(recent, strands, index)  @ 111-117
      -- The class holds one entry however many notes write it: a restrike moves its
      -- own entry to the front, and a second strand of the class takes the entry over.
  -- The objective
  -- The solve
  @fn schedule(strands, sonorities)  @ 165-191
      -- A strand is live from the onset it is chosen at to the last that reads it, both
      -- known before enumeration (§ Solving it), and listed in strand order for keying.
      @contract  strands, sonorities → per onset the strands born there, live there, and held from before  @ 164
  @fn assertAffordable(strands, plan)  @ 197-207
  @fn placementsAt(strands, born, strength)  @ 211-230
      -- Every combination of the shortlists of the strands born at an onset, with the
      -- pull each charges — the same against every state, so charged once here.
  @fn outranks(state, best, count)  @ 235-243
      -- Cost, then the choice vector, so an exact tie breaks deterministically rather than by
      -- table order (design/adaptive-tuning.md § What the solver takes).
      @contract  true iff `state` is the better of the two, the earlier candidate winning a tie  @ 234
  @fn keyOf(choice, list)  @ 245-249

# Public API (sonority.*)
  @api sonority.score(coordSet)  @ 27-43
      -- The axes are gathered before any is measured: a member holding no exponent on
      -- an axis sits at 0 there, and that 0 is only in the span once the axis is known
      -- to exist — an axis every member names does not reach back to the origin.
      @contract  coords[] → Σ over the odd primes of (highest exponent − lowest) × log₂ p  @ 26
  @api sonority.strands(notes, classOf)  @ 51-79
      -- Notes of a class that overlap hold one tuning (§ The strand); the running
      -- release is half-open, so a note struck at a release starts another.
      @contract  notes, classOf → a Strand per class per run of overlapping notes, shortlists unfilled  @ 49
      @contract  grouped by ascending class, each in strike order, whatever order the notes arrive in  @ 50
  @api sonority.walk(strands, n)  @ 122-137
      -- The whole onset is absorbed before the sonority is taken, so a chord wider
      -- than n leaves its own lowest notes standing rather than its predecessor's.
      @contract  strands, n → a Sonority per onset: last n distinct classes struck, plus sounding  @ 121
  @api sonority.cost(strands, n, strength, choice)  @ 144-158
      -- The pull is counted once per strand rather than once per note, so an octave
      -- doubling changes no answer: the box already charges it nothing.
      @contract  strands, n, strength, choice → box over the walk + strength × strain² per strand  @ 143
  @api sonority.solve(strands, n, strength)  @ 254-299
      -- The state carries the whole choice vector rather than a backpointer: two
      -- generations are alive at a time and the budget bounds them.
      @contract  strands, n, strength → the index per strand minimising sonority.cost, exactly  @ 253

